```json
{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT attr_k8s_deployment_name AS dep, metric, count(*) AS n, min(value) AS mn, max(value) AS mx FROM abnormal_metrics WHERE attr_k8s_deployment_name='geo' AND metric='k8s.deployment.available' GROUP BY ALL", "claim": "geo deployment availability is 0 for the entire abnormal window; it was 1 in normal."},
        {"kind": "trace", "sql": "SELECT 'abn' AS p, service_name, attr_span_kind, attr_status_code, count(*) AS n FROM abnormal_traces WHERE span_name='geo.Geo/Nearby' GROUP BY ALL UNION ALL SELECT 'norm', service_name, attr_span_kind, attr_status_code, count(*) FROM normal_traces WHERE span_name='geo.Geo/Nearby' GROUP BY ALL", "claim": "geo.Geo/Nearby server spans disappear in abnormal; search's client calls to geo all error (1113)."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) AS n FROM abnormal_logs WHERE message LIKE '%geo service%' GROUP BY ALL", "claim": "search logs 'Failed to get nearby hotels from geo service' hundreds of times in the abnormal window."}
      ]
    },
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT attr_k8s_deployment_name AS dep, metric, count(*) AS n, min(value) AS mn, max(value) AS mx FROM abnormal_metrics WHERE attr_k8s_deployment_name='profile' AND metric='k8s.deployment.available' GROUP BY ALL", "claim": "profile deployment availability is 0 for the entire abnormal window; it was 1 in normal."},
        {"kind": "trace", "sql": "SELECT 'abn' AS p, service_name, attr_span_kind, attr_status_code, count(*) AS n FROM abnormal_traces WHERE span_name='profile.Profile/GetProfiles' GROUP BY ALL UNION ALL SELECT 'norm', service_name, attr_span_kind, attr_status_code, count(*) FROM normal_traces WHERE span_name='profile.Profile/GetProfiles' GROUP BY ALL", "claim": "profile server spans vanish in abnormal; frontend's GetProfiles client calls all return Error (603)."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) AS n FROM abnormal_logs WHERE message='Get profiles failed' GROUP BY ALL", "claim": "frontend logs 'Get profiles failed' repeatedly in the abnormal window only."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='search' AND span_name IN ('geo.Geo/Nearby','search.Search/Nearby') GROUP BY ALL", "claim": "Every search.Search/Nearby server span errors after geo's calls fail; search's own work is otherwise unchanged."}
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('search.Search/Nearby','HTTP /hotels') GROUP BY ALL", "claim": "frontend's HTTP /hotels requests return 500 with Error status, matching failed search.Search/Nearby calls."}
      ]
    },
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('profile.Profile/GetProfiles','HTTP /recommendations') GROUP BY ALL", "claim": "frontend's HTTP /recommendations requests return 500, matching failed profile.Profile/GetProfiles calls."}
      ]
    }
  ]
}
